package com.madibaev.itracker;
import android.annotation.SuppressLint;import android.app.Activity;import android.graphics.Color;import android.os.Bundle;import android.view.Window;import android.view.WindowInsets;import android.view.WindowInsetsController;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;
public class MainActivity extends Activity { WebView w; @SuppressLint("SetJavaScriptEnabled") public void onCreate(Bundle b){super.onCreate(b);Window win=getWindow();win.setStatusBarColor(Color.rgb(5,5,5));win.setNavigationBarColor(Color.rgb(5,5,5));if(android.os.Build.VERSION.SDK_INT>=30){win.setStatusBarColor(Color.rgb(5,5,5));win.setNavigationBarColor(Color.rgb(5,5,5));win.setStatusBarContrastEnforced(false);win.setNavigationBarContrastEnforced(false);win.setDecorFitsSystemWindows(true);}w=new WebView(this);w.setBackgroundColor(Color.rgb(5,5,5));WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDefaultTextEncodingName("utf-8");w.setWebViewClient(new WebViewClient());w.setWebChromeClient(new WebChromeClient());w.loadUrl("file:///android_asset/www/index.html");setContentView(w);} @Override public void onBackPressed(){if(w!=null&&w.canGoBack())w.goBack();else super.onBackPressed();}}
